export function Inbox({ status, messages, error }) {
  if (status === "loading") return <p role="status">Loading messages...</p>;
  if (status === "error") return <p role="alert">Couldn't load messages. {error}</p>;

  const unread = messages.filter((m) => !m.read).length;

  return (
    <section aria-labelledby="inbox-title">
      <h2 id="inbox-title">
        Inbox {unread > 0 && <span className="badge">{unread} unread</span>}
      </h2>
      {messages.length === 0 ? (
        <p>No messages yet.</p>
      ) : (
        <ul>{/* rows come in the lists lesson. */}</ul>
      )}
    </section>
  );
}
```

| Choice | Pattern |
|---|---|
| whole component differs (loading, error). | early return. |
| A or B. | ternary. |
| B or nothing. | `boolean && <B />`. |
| complex logic. | compute a variable before return. |

